/// Stroke templates for the numbers 0 to 10 (Number Galaxy).
///
/// Drawn by hand as simple school-style numerals and checked only by eye, so
/// `strokeOrderVerified` is false: a teacher must confirm the stroke order and
/// direction before any child can earn handwriting mastery. Regenerate from the
/// design tool, do not edit the numbers by hand.
library;

import 'stroke_template.dart';

Stroke _s(List<double> xy) =>
    [for (var i = 0; i < xy.length; i += 2) Pt(xy[i], xy[i + 1])];

